-- talents whose Russian description in the game is outdated: our own text, {1} {2} are the numbers of the rank
AdeTalents.TextRu = {
  ["Balance of All Things"] = { text = "Нанесение урона цели, пораженной Роем насекомых, с помощью Гнева возвращает {1}% стоимости его маны.\n\nУ Звездного огня на {2}% повышен шанс критического удара по целям, пораженным Лунным огнем." },
  ["Kill Command"] = { text = "Приказывает питомцу мгновенно атаковать, нанося {1}% от его силы атаки. Можно использовать только после критического удара охотника по цели." },
  ["Unleashed Potential"] = { text = "Попадания ваших заклинаний прямого урона позволяют демону получать {1}% от бонуса к урону ваших заклинаний Огня и Тьмы на {2} сек. Каждый такт заклинаний воронки обновляет длительность. Суммируется до {3} раз." },
  ["Shadow of Death"] = { text = "Завершающий прием: накладывает на цель печать на {1} сек. Печать накапливает часть урона, который получает цель, до предела в процентах от вашей силы атаки, и затем высвобождает его в виде физического урона. Растет с каждым очком комбо (накопленный урон / предел от силы атаки):\n1 очко: {3}% / {4}%\n2 очка: {6}% / {7}%\n3 очка: {9}% / {10}%\n4 очка: {12}% / {13}%\n5 очков: {15}% / {16}%" },
  ["Experimental Ammunition"] = { text = "Ваш Прицельный выстрел наносит дополнительно {1}% урона в виде урона от Огня, Тайной магии или Природы в зависимости от активного эффекта. Также дает бонус:\n- Разрывные боеприпасы: следующий Залп вызывает взрывы, нанося {2}% урона оружия дальнего боя врагам в радиусе {3} м от целей.\n- Ядовитые боеприпасы: следующий Укус змеи наносит на {4}% больше урона и снижает броню цели на {5} на {6} сек.\n- Зачарованные боеприпасы: следующий Чародейский выстрел наносит на {7}% больше урона, и цель получает на {8}% больше магического урона в течение {9} сек." },
  ["Demonic Sacrifice"] = { text = "При активации приносит в жертву призванного демона, чтобы дать вам эффект. Эффект отменяется, если призван или порабощен любой другой демон.\nБес: урон заклинаний +{1}%.\nДемон Бездны: {2}% здоровья каждые {3} сек.\nСуккуб: создаваемая угроза -{4}%.\nОхотник Скверны: {5}% маны каждые {6} сек.", single = true },
  ["Throwing Weapon Specialization"] = { text = "Увеличивает дальность Броска и Смертельного броска на {1} м. и дает вашему Смертельному броску {2}% шанс применить яд оружия левой руки.", name = "Специализация на метательном оружии" },
}
